files.lib/units.sh:
valid_unit_label() {
    case "$1" in
        ""|*[!a-z0-9-]*) return 1 ;;
        *) return 0 ;;
    esac
}
unit_filename() {
    printf '%s.service\n' "$1"
}

files.tests/units.sh:
#!/bin/bash
set -eu
source lib/units.sh
check_uppercase_rejected() {
    if valid_unit_label "CacheNode"; then
        printf '%s\n' 'uppercase label accepted' >&2
        return 1
    fi
}
check_suffix() {
    [ "$(unit_filename cache-node)" = "cache-node.service" ]
}
check_uppercase_rejected
check_suffix
